def max_expression_value(E, P, M):
    def evaluate(expression, plus_count, minus_count):
        if not expression:
            return 0

        if expression[0].isdigit():
            num = int(expression[0])
            if len(expression) == 1:
                return num
            else:
                return num * evaluate(expression[1:], plus_count, minus_count)

        if expression[0] == '(':
            depth = 0
            for i in range(1, len(expression)):
                if expression[i] == '(':
                    depth += 1
                elif expression[i] == ')':
                    depth -= 1
                if depth == 0:
                    sub_expr = expression[1:i]
                    remaining_expr = expression[i+1:]
                    break

            left_value = evaluate(sub_expr, plus_count, minus_count)
            if remaining_expr[0] == '?':
                if plus_count > 0:
                    return left_value + evaluate(remaining_expr[1:], plus_count - 1, minus_count)
                elif minus_count > 0:
                    return left_value - evaluate(remaining_expr[1:], plus_count, minus_count - 1)
            else:
                right_value = evaluate(remaining_expr, plus_count, minus_count)
                if remaining_expr[0] == '+':
                    return left_value + right_value
                else:
                    return left_value - right_value

    return evaluate(E, P, M)

